$c=New-Object System.Data.SqlClient.SqlConnection 'Server=THUONGNGUYEN\MSSQLSV;Database=NYCTaxi_DWH;Integrated Security=True;Connect Timeout=10';$c.Open()
try {$cmd=$c.CreateCommand();$cmd.CommandText="SELECT r.session_id,r.status,r.command,r.wait_type,r.blocking_session_id,r.total_elapsed_time/1000 AS seconds,r.cpu_time/1000 AS cpu_seconds, LEFT(t.text,120) AS sql_start FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE r.database_id=DB_ID() AND r.session_id<>@@SPID";$a=New-Object System.Data.SqlClient.SqlDataAdapter $cmd;$t=New-Object System.Data.DataTable;$null=$a.Fill($t);$t|Format-Table -AutoSize} finally {$c.Dispose()}
